// One item per active feed row. A row without a usable URL is still passed on, so it is reported as failed.
const rows = $('Load Active Feeds').all().map((i) => i.json).filter((r) => r.id !== undefined);
return rows.map((r) => ({ json: { feed_id: r.id, name: String(r.name ?? '').trim(), url: String(r.url ?? '').trim() } }));

// Result of one feed: an error text, or the parsed XML. Runs once per feed inside the loop.
const feed = $('Loop Over Feeds').first().json;
const fetched = $('Fetch Feed XML').first().json;
const parsed = $input.first().json;
const squash = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
let error = '';
if (fetched.error) {
  const e = fetched.error;
  error = squash(typeof e === 'string' ? e : e.message || e.description || JSON.stringify(e)).slice(0, 200) || 'The request failed.';
} else if (!parsed || !Object.keys(parsed).length) error = 'The response is not valid XML.';
return [{ json: { feed_id: feed.feed_id, name: feed.name, url: feed.url, error, xml: error ? null : parsed } }];

// Turns the fetched feeds into one digest. Nothing is written here.
const s = $('RSS Digest Settings').first().json;
const retentionDays = Math.max(1, Number(s.retention_days) || 30);
const maxItems = Math.max(1, Math.floor(Number(s.max_items_per_digest) || 50));
const now = DateTime.now().setZone($now.zoneName);
const cutoff = now.minus({ days: retentionDays }).toMillis();

// Same link = same key: no scheme, lowercase host without www., no #fragment, no trailing slash,
// no utm_* or click-id parameters, remaining parameters sorted.
const TRACKING = /^(utm_.*|fbclid|gclid|gclsrc|dclid|gbraid|wbraid|msclkid|yclid|twclid|igshid|mc_cid|mc_eid|_hsenc|_hsmi|mkt_tok)$/i;
function linkKey(raw) {
  const m = String(raw ?? '').trim().match(/^https?:\/\/([^\/?#\s]+)([^?#\s]*)(\?[^#\s]*)?(#\S*)?$/i);
  if (!m) return '';
  const host = m[1].toLowerCase().replace(/^[^@]*@/, '').replace(/^www\./, '').replace(/:(80|443)$/, '');
  const name = (p) => { try { return decodeURIComponent(p.split('=')[0]); } catch (e) { return p.split('=')[0]; } };
  const params = (m[3] || '').slice(1).split('&').filter((p) => p && !TRACKING.test(name(p))).sort();
  return 'url:' + host + m[2].replace(/\/+$/, '') + (params.length ? '?' + params.join('&') : '');
}
const squash = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const titleKey = (t) => 'title:' + squash(t).toLowerCase();

// XML values arrive as strings, objects with "_" text and attributes, or arrays.
const text = (v) => (v == null ? '' : Array.isArray(v) ? text(v[0]) : typeof v === 'object' ? text(v._ ?? '') : String(v));
const decode = (t) => t.replace(/&nbsp;/g, ' ').replace(/&#(\d+);/g, (m, d) => String.fromCodePoint(Number(d))).replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const plain = (v) => squash(decode(text(v).replace(/<[^>]*>/g, ' ')));
const list = (v) => (v == null ? [] : Array.isArray(v) ? v : [v]);
function atomLink(v) {
  const links = list(v).map((l) => (typeof l === 'string' ? { href: l } : l || {}));
  const best = links.find((l) => !l.rel || l.rel === 'alternate') || links[0];
  return best ? String(best.href ?? text(best)) : '';
}
function toMillis(v) {
  const t = text(v).trim();
  if (!t) return null;
  const ms = Date.parse(t);
  return Number.isFinite(ms) ? ms : null;
}

// Keywords: case-insensitive, whole word or phrase (letters and digits around it do not count as a match).
const escRe = (t) => t.replace(/[.*+?^$\{\}()|[\]\\]/g, '\\$&');
const keywordRows = $('Load Keywords').all().map((i) => i.json).filter((r) => r.id !== undefined && squash(r.keyword));
const toRule = (r) => ({ word: squash(r.keyword), re: new RegExp('(?<![\\p{L}\\p{N}_])' + squash(r.keyword).split(' ').map(escRe).join('\\s+') + '(?![\\p{L}\\p{N}_])', 'iu') });
const includes = keywordRows.filter((r) => r.exclude !== true).map(toRule);
const excludes = keywordRows.filter((r) => r.exclude === true).map(toRule);

const history = new Map();
for (const r of $('Load Sent History').all().map((i) => i.json)) if (r.id !== undefined && r.item_key) history.set(r.item_key, r);

// One result per feed from Tag Feed Result: the feed row, an error text or the parsed XML.
const feeds = $input.all().map((i) => i.json).filter((f) => f.feed_id !== undefined);

const failed = [], candidates = [], touch = [], seenThisRun = new Set();
const stats = { feeds: feeds.length, items: 0, already_sent: 0, too_old: 0, keyword_skipped: 0, repeated: 0, no_link_or_title: 0 };
feeds.forEach((feed, i) => {
  const name = squash(feed.name) || feed.url;
  if (feed.error) return failed.push({ name, url: feed.url, error: feed.error });
  const x = feed.xml || {};
  let entries;
  if (x.rss) entries = list(x.rss.channel?.item);
  else if (x.feed) entries = list(x.feed.entry);
  else if (x['rdf:RDF']) entries = list(x['rdf:RDF'].item);
  else return failed.push({ name, url: feed.url, error: 'The response is not an RSS or Atom feed.' });
  for (const e of entries) {
    stats.items++;
    const title = plain(e.title);
    const isAtom = Boolean(x.feed);
    let link = isAtom ? atomLink(e.link) : squash(text(e.link));
    if (!link && !isAtom && e.guid && (typeof e.guid !== 'object' || e.guid.isPermaLink !== 'false')) link = squash(text(e.guid));
    const key = linkKey(link) || (title ? titleKey(title) : '');
    if (!key) { stats.no_link_or_title++; continue; }
    const dateMs = toMillis(e.pubDate ?? e['dc:date'] ?? e.published ?? e.updated);
    if (dateMs !== null && dateMs < cutoff) { stats.too_old++; continue; }
    const sent = history.get(key);
    if (sent) {
      stats.already_sent++;
      // Keeps the history row at least as new as the item, so retention never removes the row of an item
      // that is still in a feed and still inside the window. Undated items count as seen now.
      const effective = dateMs ?? now.toMillis();
      const last = Date.parse(sent.last_seen);
      if (!Number.isFinite(last) || effective > last) touch.push({ id: sent.id, last_seen: new Date(effective).toISOString() });
      continue;
    }
    if (seenThisRun.has(key)) { stats.repeated++; continue; }
    const summary = plain(e.description ?? e.summary ?? e['content:encoded'] ?? e.content);
    const haystack = title + ' ' + summary;
    const matched = includes.filter((k) => k.re.test(haystack)).map((k) => k.word);
    if ((includes.length && !matched.length) || excludes.some((k) => k.re.test(haystack))) { stats.keyword_skipped++; continue; }
    seenThisRun.add(key);
    candidates.push({ key, feed_name: name, feed_index: i, title: title || link, link, date_ms: dateMs, matched, summary: summary.length > 280 ? summary.slice(0, 277) + '...' : summary });
  }
});

// Newest first; undated items count as published now. Items over the limit wait for the next run.
candidates.sort((a, b) => (b.date_ms ?? now.toMillis()) - (a.date_ms ?? now.toMillis()));
const picked = candidates.slice(0, maxItems);
const overflow = candidates.length - picked.length;

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const fmt = (ms) => (ms === null ? '' : DateTime.fromMillis(ms).setZone($now.zoneName).toFormat('d LLL yyyy, HH:mm'));
let html = '<h2 style="font-family:sans-serif">' + picked.length + ' new item' + (picked.length === 1 ? '' : 's') + '</h2>';
if (failed.length) html += '<p style="font-family:sans-serif;color:#b00020"><b>Could not read ' + failed.length + ' feed' + (failed.length === 1 ? '' : 's') + ':</b></p><ul style="font-family:sans-serif">' + failed.map((f) => '<li>' + esc(f.name) + ' (' + esc(f.url) + '): ' + esc(f.error) + '</li>').join('') + '</ul>';
const groups = [...new Set(picked.map((p) => p.feed_index))].sort((a, b) => a - b);
for (const g of groups) {
  const items = picked.filter((p) => p.feed_index === g);
  html += '<h3 style="font-family:sans-serif">' + esc(items[0].feed_name) + '</h3><ul style="font-family:sans-serif">';
  for (const p of items) {
    const head = /^https?:\/\//i.test(p.link) ? '<a href="' + esc(p.link) + '">' + esc(p.title) + '</a>' : esc(p.title);
    const meta = [fmt(p.date_ms), p.matched.length ? 'matched: ' + p.matched.map(esc).join(', ') : ''].filter(Boolean).join(' &middot; ');
    html += '<li style="margin-bottom:10px">' + head + (meta ? '<br><small>' + meta + '</small>' : '') + (p.summary ? '<br>' + esc(p.summary) : '') + '</li>';
  }
  html += '</ul>';
}
if (overflow > 0) html += '<p style="font-family:sans-serif">' + overflow + ' more new item' + (overflow === 1 ? '' : 's') + ' will come in the next digest.</p>';

const sentAt = now.toMillis();
return [{ json: {
  new_count: picked.length,
  overflow,
  failed,
  stats,
  touch,
  subject: 'RSS digest: ' + picked.length + ' new item' + (picked.length === 1 ? '' : 's') + (failed.length ? ', ' + failed.length + ' feed' + (failed.length === 1 ? '' : 's') + ' failed' : ''),
  html,
  sent: picked.map((p) => ({ item_key: p.key, feed_name: p.feed_name, title: p.title.slice(0, 500), link: p.link.slice(0, 2000), last_seen: new Date(Math.max(sentAt, p.date_ms ?? 0)).toISOString() })),
} }];
